        num_piles = len(piles)
        num_stones = sum(piles)
        num_stones_per_pile = num_stones // num_piles

        # Helper function to check if a player wins with a given pile
        def check_if_wins(player, pile_index):
            if player == 1:
                return num_stones_per_pile * (player + 1) <= num_piles * num_stones_per_pile
            else:
                return num_stones_per_pile * (player + 1) >= num_piles * num_stones_per_pile

        # Check if the game is a tie
