```matlab
% Milling Chatter Stability Lobe Diagram

% Parameters
tooth_count = 10; % Number of teeth
diameter = 50; % Milling tool diameter (mm)
spindle_speed = 100:100:5000; % Spindle speed range (RPM)

% Modal Damping, Stiffness, and Mass (Modal parameters from impact test)
modal_damping_ratio = 0.1;
modal_stiffness = 1e6; % (N/m)
modal_mass = 1; % (kg)

% Tooth passing frequency (Hz)
tpf = spindle_speed * tooth_count / 60;

% Stability Lobe Calculation
critical_depths = sqrt((8 * modal_mass * (2 * pi * tpf).^2) ./ (modal_stiffness * (1 - modal_damping_ratio^2)));

% Plot Stability Lobe Diagram
figure;
plot(spindle_speed, critical_depths, 'LineWidth', 2);
title('Chatter Stability Lobe Diagram');
xlabel('Spindle Speed (RPM)');
ylabel('Critical Axial Depth of Cut (mm)');
grid on;
```

