        if (n % i == 0) return false;
    }
    return true;
}

vector<int> sieveOfEratosthenes(int n) {
    vector<int> primes;
    primes.push_back(2);
    for (int i = 3; i <= n; i += 2) {
        if (isPrime(i)) primes.push_back(i);
    }
    for (int i = 3; i <= ceil(sqrt(n)); i += 2) {
        if (primes[primes.size() - 1] == i) {
            for (int j = i*i; j <= n; j += i) {
