Here's the code for the `remove_duplicate_characters` function:
```rust
fn remove_duplicate_characters(input: &str) -> String {
    let mut unique_characters: Vec<char> = Vec::new();
    let mut result: String = String::new();

    for character in input.chars() {
        if !unique_characters.contains(&character) {
            unique_characters.push(character);
            result.push(character);
        }
    }

    result
}
